result:
**Playtest notes**
- The game loads, starts, scores, can be lost and can be restarted. The report scored 8 of 8 with no console errors.
- The menu is clear and the controls are explained. The HUD is readable.
- The bot lost in about 6.6s. Hazards spawn aimed at the player and can appear right next to them, so some hits feel unfair.
- Orbs expire silently. The only warning is a blink in the last 2 seconds, and a missed orb costs a life. A visible countdown ring would make that fair.
- Collecting is steady but flat. Every orb is worth the same, so there is no risk and reward decision.
- Hazards bounce forever and pile up to the cap of 14. Difficulty rises through speed, spawn rate and chasers, which works.
- The strip under the HUD (y<80) is empty, and the background is a plain gradient with no sense of motion.
- Changes I'm making:
  - **Orb timer rings:** each orb shows how long it has left.
  - **Hazard spawn distance:** hazards can no longer spawn close to the player.
  - **Golden bonus orb:** it appears occasionally, is worth 3 points and is risky to chase. It expires without costing a life.
  - **Extra-orb bug:** the extra orb every 5 points could be skipped by a +3 score jump, so I fixed how it triggers.
  - **Starfield:** a drifting starfield behind the action.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Orb Runner</title>
<style>
  html,body{margin:0;height:100%;background:#05050f;display:flex;align-items:center;justify-content:center;overflow:hidden}
  canvas{background:radial-gradient(circle at 50% 40%,#10103a,#05050f);border:2px solid #2a2a6a;box-shadow:0 0 30px #2a2aff55;max-width:100vw;max-height:100vh}
</style>
</head>
<body>
<canvas id="c" width="800" height="600"></canvas>
<script>
(() => {
  const cv = document.getElementById('c'), ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  const WIN_SCORE = 40, ORB_LIFE = 7, MAX_HAZ = 14, TOP = 80;
  window.gameState = { score: 0, state: "menu" };

  let state = "menu", score = 0, lives = 3, time = 0, last = 0, paused = false;
  let player, orbs, hazards, pending, particles, floats, spawnT, invuln, keys = {}, mouse = null, shake = 0;
  let combo = 0, comboT = 0, dash = 0, dashCd = 0, best = 0, newBest = false, lvlFlash = 0, lastLvl = 1, goldT = 10;
  const stars = [];
  for (let i = 0; i < 60; i++) stars.push({ x: Math.random() * W, y: Math.random() * H, s: 0.5 + Math.random() * 1.5, v: 5 + Math.random() * 20 });
  try { best = parseInt(localStorage.getItem('orbrunner_best')) || 0; } catch (e) {}

  // ---------- audio ----------
  let actx = null;
  function beep(freq, dur, type = 'sine', vol = 0.12, slide = 0) {
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      if (actx.state === 'suspended') actx.resume();
      const o = actx.createOscillator(), g = actx.createGain();
      o.type = type; o.frequency.value = freq;
      if (slide) o.frequency.linearRampToValueAtTime(Math.max(20, freq + slide), actx.currentTime + dur);
      g.gain.setValueAtTime(vol, actx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, actx.currentTime + dur);
      o.connect(g); g.connect(actx.destination);
      o.start(); o.stop(actx.currentTime + dur);
    } catch (e) {}
  }

  function sync() { window.gameState = { score: score, state: state }; }

  function reset() {
    player = { x: W / 2, y: H / 2 + 30, r: 14, speed: 300 };
    orbs = []; hazards = []; pending = []; particles = []; floats = [];
    score = 0; lives = 3; time = 0; spawnT = 0; invuln = 0; shake = 0; goldT = 10;
    combo = 0; comboT = 0; dash = 0; dashCd = 0; paused = false; newBest = false; lvlFlash = 0; lastLvl = 1;
    for (let i = 0; i < 3; i++) spawnOrb();
    for (let i = 0; i < 3; i++) queueHazard(0.3 + i * 0.4);
  }

  function start() {
    reset(); state = "playing"; sync();
    beep(440, 0.15, 'square', 0.08, 220);
  }

  function endGame(s) {
    state = s;
    if (score > best) { best = score; newBest = true; try { localStorage.setItem('orbrunner_best', best); } catch (e) {} }
    sync();
  }

  function spawnOrb(gold) {
    let x, y, tries = 0;
    do {
      x = 40 + Math.random() * (W - 80); y = TOP + Math.random() * (H - TOP - 40); tries++;
    } while (tries < 20 && Math.hypot(x - player.x, y - player.y) < 80);
    const life = gold ? 4.5 : ORB_LIFE;
    orbs.push({ x, y, r: gold ? 12 : 10, ph: Math.random() * 6, life, max: life, gold: !!gold });
  }

  function queueHazard(delay = 0.9) {
    if (hazards.length + pending.length >= MAX_HAZ) return;
    let x, y, tries = 0;
    do {
      const side = Math.floor(Math.random() * 4);
      if (side === 0) { x = 14; y = TOP + Math.random() * (H - TOP - 20); }
      else if (side === 1) { x = W - 14; y = TOP + Math.random() * (H - TOP - 20); }
      else if (side === 2) { x = 14 + Math.random() * (W - 28); y = TOP; }
      else { x = 14 + Math.random() * (W - 28); y = H - 14; }
      tries++;
    } while (tries < 15 && player && Math.hypot(x - player.x, y - player.y) < 170);
    const chaser = time > 35 ? Math.random() < 0.35 : (time > 15 && Math.random() < 0.25);
    pending.push({ x, y, t: delay, chaser });
  }

  function spawnHazard(p) {
    const diff = 1 + time / 20;
    const sp = (70 + Math.random() * 50) * Math.min(diff, 3.2) * (p.chaser ? 0.7 : 1);
    const a = Math.atan2(player.y - p.y, player.x - p.x) + (Math.random() - 0.5) * (p.chaser ? 0.3 : 1.2);
    hazards.push({ x: p.x, y: p.y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, sp, chaser: p.chaser,
      r: 12 + Math.random() * 8, rot: 0 });
  }

  function burst(x, y, color, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * 6.283, s = 40 + Math.random() * 160;
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 0.5 + Math.random() * 0.4, max: 0.9, color });
    }
  }
  function floatText(t, x, y, color) { floats.push({ t, x, y, color, life: 0.8 }); }

  // ---------- input ----------
  function togglePause() { if (state === "playing") paused = !paused; }
  addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    keys[k] = true;
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
    if (state !== "playing" && (e.key === ' ' || e.key === 'Enter')) start();
    else if (state === "playing" && (k === 'p' || k === 'escape')) togglePause();
    else if (state === "playing" && paused && (k === ' ' || k === 'enter')) paused = false;
    if (k === 'shift' && state === "playing" && !paused && dashCd <= 0) {
      dash = 0.25; dashCd = 2; beep(300, 0.15, 'triangle', 0.08, 400);
    }
    if (k !== 'shift') mouse = null;
  });
  addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
  addEventListener('blur', () => { if (state === "playing") paused = true; keys = {}; });
  function mpos(e) {
    const r = cv.getBoundingClientRect();
    return { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height };
  }
  cv.addEventListener('mousemove', e => { mouse = mpos(e); });
  cv.addEventListener('mousedown', e => {
    if (state !== "playing") start();
    else if (paused) paused = false;
    else if (dashCd <= 0 && e.button === 2) { dash = 0.25; dashCd = 2; beep(300, 0.15, 'triangle', 0.08, 400); }
    mouse = mpos(e);
  });
  cv.addEventListener('contextmenu', e => e.preventDefault());

  function loseLife() {
    lives--; invuln = 1.5; shake = 10; combo = 0;
    burst(player.x, player.y, '#f55', 25);
    beep(120, 0.4, 'sawtooth', 0.15, -80);
    if (lives <= 0) endGame("over");
  }

  // ---------- update ----------
  function update(dt) {
    for (const s of stars) { s.y += s.v * dt; if (s.y > H) { s.y = 0; s.x = Math.random() * W; } }
    if (state !== "playing") { updateParticles(dt); return; }
    if (paused) return;
    time += dt;
    invuln = Math.max(0, invuln - dt);
    shake = Math.max(0, shake - dt * 30);
    dash = Math.max(0, dash - dt);
    dashCd = Math.max(0, dashCd - dt);
    lvlFlash = Math.max(0, lvlFlash - dt);
    const lv = 1 + Math.floor(time / 15);
    if (lv > lastLvl) { lastLvl = lv; lvlFlash = 1.2; beep(520, 0.25, 'square', 0.07, 300); }
    if (comboT > 0) { comboT -= dt; if (comboT <= 0) combo = 0; }

    goldT -= dt;
    if (goldT <= 0) { goldT = 12 + Math.random() * 8; if (!orbs.some(o => o.gold)) spawnOrb(true); }

    const spd = player.speed * (dash > 0 ? 2.2 : 1);
    let dx = 0, dy = 0;
    if (keys['arrowleft'] || keys['a']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;
    if (dx || dy) {
      const l = Math.hypot(dx, dy);
      player.x += dx / l * spd * dt; player.y += dy / l * spd * dt;
    } else if (mouse) {
      const ddx = mouse.x - player.x, ddy = mouse.y - player.y, d = Math.hypot(ddx, ddy);
      const step = Math.min(d, spd * 1.5 * dt);
      if (d > 1) { player.x += ddx / d * step; player.y += ddy / d * step; }
    }
    player.x = Math.max(player.r, Math.min(W - player.r, player.x));
    player.y = Math.max(player.r, Math.min(H - player.r, player.y));

    spawnT += dt;
    const interval = Math.max(0.7, 3.2 - time * 0.04);
    if (spawnT > interval) { spawnT = 0; queueHazard(); }
    for (let i = pending.length - 1; i >= 0; i--) {
      pending[i].t -= dt;
      if (pending[i].t <= 0) { spawnHazard(pending[i]); pending.splice(i, 1); }
    }

    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      o.ph += dt * 4; o.life -= dt;
      if (o.life <= 0) {
        orbs.splice(i, 1);
        if (o.gold) { burst(o.x, o.y, '#fd4', 8); continue; }
        burst(o.x, o.y, '#f55', 10); combo = 0;
        floatText('MISSED -♥', o.x, o.y, '#f66');
        spawnOrb();
        if (state === "playing") { lives--; shake = 6; beep(150, 0.3, 'sawtooth', 0.1, -60); if (lives <= 0) { endGame("over"); return; } }
        continue;
      }
      if (Math.hypot(o.x - player.x, o.y - player.y) < o.r + player.r) {
        orbs.splice(i, 1);
        const prev = score;
        score += o.gold ? 3 : 1;
        combo++; comboT = 2.5;
        burst(o.x, o.y, o.gold ? '#fd4' : '#6ff', o.gold ? 24 : 14);
        floatText(o.gold ? '+3' : '+1', o.x, o.y, o.gold ? '#fd4' : '#6ff');
        beep(660 + Math.min(score, 20) * 20 + Math.min(combo, 8) * 30, 0.12, 'sine', 0.12, 300);
        if (combo > 0 && combo % 5 === 0 && lives < 5) { lives++; floatText('+♥', player.x, player.y - 20, '#f88'); beep(990, 0.3, 'triangle', 0.12, 300); }
        if (!o.gold) spawnOrb();
        if (Math.floor(score / 5) > Math.floor(prev / 5) && orbs.length < 5) spawnOrb();
        if (score >= WIN_SCORE) { endGame("won"); beep(880, 0.5, 'triangle', 0.15, 400); }
        else sync();
      }
    }
    if (state !== "playing") return;

    for (let i = hazards.length - 1; i >= 0; i--) {
      const h = hazards[i];
      if (h.chaser) {
        const want = Math.atan2(player.y - h.y, player.x - h.x), cur = Math.atan2(h.vy, h.vx);
        let da = want - cur; while (da > Math.PI) da -= 6.283; while (da < -Math.PI) da += 6.283;
        const na = cur + Math.max(-1.1 * dt, Math.min(1.1 * dt, da));
        h.vx = Math.cos(na) * h.sp; h.vy = Math.sin(na) * h.sp;
      }
      h.x += h.vx * dt; h.y += h.vy * dt; h.rot += dt * 3;
      if (h.x < h.r && h.vx < 0 || h.x > W - h.r && h.vx > 0) h.vx *= -1;
      if (h.y < TOP - 30 + h.r && h.vy < 0 || h.y > H - h.r && h.vy > 0) h.vy *= -1;
      if (invuln <= 0 && dash <= 0 && Math.hypot(h.x - player.x, h.y - player.y) < h.r * 0.85 + player.r * 0.8) {
        loseLife();
        if (state !== "playing") break;
      }
    }
    updateParticles(dt);
  }

  function updateParticles(dt) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx * dt; p.y += p.vy * dt; p.life -= dt;
      if (p.life <= 0) particles.splice(i, 1);
    }
    for (let i = floats.length - 1; i >= 0; i--) {
      const f = floats[i]; f.y -= 40 * dt; f.life -= dt;
      if (f.life <= 0) floats.splice(i, 1);
    }
  }

  // ---------- draw ----------
  function glowCircle(x, y, r, color, blur) {
    ctx.shadowColor = color; ctx.shadowBlur = blur;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, Math.max(0.5, r), 0, 6.283); ctx.fill();
    ctx.shadowBlur = 0;
  }

  function text(t, x, y, size, color, align = 'center') {
    ctx.font = `bold ${size}px 'Courier New', monospace`;
    ctx.fillStyle = color; ctx.textAlign = align;
    ctx.fillText(t, x, y);
  }

  function spike(r, fill, glow) {
    ctx.shadowColor = glow; ctx.shadowBlur = 15; ctx.fillStyle = fill;
    ctx.beginPath();
    for (let i = 0; i < 16; i++) {
      const rr = i % 2 ? r * 0.6 : r * 1.15, a = i / 16 * 6.283;
      ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
    }
    ctx.closePath(); ctx.fill();
    ctx.shadowBlur = 0;
  }

  function draw() {
    ctx.save();
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#9ab';
    for (const s of stars) { ctx.globalAlpha = 0.15 + s.s * 0.15; ctx.fillRect(s.x, s.y, s.s, s.s); }
    ctx.globalAlpha = 1;
    if (shake > 0) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);

    if (state !== "menu") {
      for (const p of pending) {
        const f = 0.5 + 0.5 * Math.sin(p.t * 25);
        ctx.globalAlpha = 0.4 + 0.6 * f;
        ctx.strokeStyle = p.chaser ? '#c6f' : '#f55'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(p.x, p.y, 10 + p.t * 14, 0, 6.283); ctx.stroke();
        text('!', p.x, p.y + 6, 16, p.chaser ? '#c6f' : '#f55');
      }
      ctx.globalAlpha = 1;
      for (const o of orbs) {
        const col = o.gold ? '#fd4' : '#5ff';
        ctx.globalAlpha = o.life < 2 ? (Math.floor(o.life * 8) % 2 ? 0.35 : 1) : 1;
        glowCircle(o.x, o.y, o.r + Math.sin(o.ph) * 2, col, 25);
        ctx.strokeStyle = o.life < 2 ? '#f66' : col; ctx.lineWidth = 2; ctx.globalAlpha *= 0.7;
        ctx.beginPath(); ctx.arc(o.x, o.y, o.r + 8, -Math.PI / 2, -Math.PI / 2 + 6.283 * Math.max(0, o.life / o.max)); ctx.stroke();
      }
      ctx.globalAlpha = 1;
      for (const h of hazards) {
        ctx.save(); ctx.translate(h.x, h.y); ctx.rotate(h.rot);
        if (h.chaser) spike(h.r, '#a3e', '#c6f'); else spike(h.r, '#e22', '#f33');
        ctx.restore();
      }
      ctx.shadowBlur = 0;
      if (state !== "over" && !(invuln > 0 && Math.floor(invuln * 12) % 2)) {
        glowCircle(player.x, player.y, player.r, dash > 0 ? '#fff' : '#ffd84a', dash > 0 ? 35 : 22);
      }
      for (const p of particles) {
        ctx.globalAlpha = Math.max(0, p.life / p.max);
        glowCircle(p.x, p.y, 3, p.color, 8);
      }
      for (const f of floats) {
        ctx.globalAlpha = Math.max(0, f.life / 0.8);
        text(f.t, f.x, f.y, 16, f.color);
      }
      ctx.globalAlpha = 1;

      text('SCORE ' + score + ' / ' + WIN_SCORE, 16, 30, 22, '#fff', 'left');
      text('BEST ' + best, 16, 52, 14, '#889', 'left');
      text('LIVES ' + '♥'.repeat(Math.max(0, lives)), W - 16, 30, 22, '#f66', 'right');
      const lvl = 1 + Math.floor(time / 15);
      text('LEVEL ' + lvl, W / 2, 30, 18, lvlFlash > 0 && Math.floor(lvlFlash * 8) % 2 ? '#fff' : '#9af');
      if (combo > 1) text('COMBO x' + combo + (combo % 5 ? '' : ' +♥'), W / 2, 54, 16, '#ffd84a');
      ctx.fillStyle = '#223'; ctx.fillRect(W - 116, 42, 100, 6);
      ctx.fillStyle = dashCd > 0 ? '#58a' : '#5ff'; ctx.fillRect(W - 116, 42, 100 * (1 - dashCd / 2), 6);
      text('SHIFT dash (safe)', W - 16, 66, 12, '#889', 'right');
    }

    if (state === "menu") {
      text('ORB RUNNER', W / 2, 150, 64, '#5ff');
      const lx = 170, tx = 205;
      glowCircle(lx, 212, 8, '#5ff', 20);
      text('Collect glowing orbs. Missed orbs cost a life!', tx, 218, 18, '#cfe', 'left');
      ctx.save(); ctx.translate(lx, 252); ctx.rotate(0.3); spike(10, '#e22', '#f33'); ctx.restore();
      text('Avoid the red spikes', tx, 258, 18, '#fcc', 'left');
      ctx.save(); ctx.translate(lx, 292); ctx.rotate(0.3); spike(10, '#a3e', '#c6f'); ctx.restore();
      text('Purple spikes hunt you later on', tx, 298, 18, '#e9f', 'left');
      glowCircle(lx, 332, 8, '#fd4', 20);
      text('Golden orbs = 3 points (no penalty if missed)', tx, 338, 18, '#fe9', 'left');
      text('Move: WASD / Arrows, or the mouse', W / 2, 380, 20, '#fff');
      text('SHIFT (or right-click) = dash, safe from spikes', W / 2, 406, 18, '#fff');
      text('P / Esc = pause', W / 2, 430, 18, '#fff');
      text('Reach ' + WIN_SCORE + ' points to win. 5 orbs in a combo = +1 life.', W / 2, 460, 16, '#9af');
      if (best) text('Best: ' + best, W / 2, 484, 16, '#889');
      text('Click or press SPACE to start', W / 2, 535, 26, '#ffd84a');
    } else if (paused && state === "playing") {
      ctx.fillStyle = 'rgba(0,0,0,0.55)'; ctx.fillRect(0, 0, W, H);
      text('PAUSED', W / 2, 280, 56, '#9af');
      text('Press P, SPACE or click to resume', W / 2, 335, 20, '#fff');
    } else if (state === "over" || state === "won") {
      ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(0, 0, W, H);
      if (state === "over") text('GAME OVER', W / 2, 250, 60, '#f55');
      else text('YOU WIN!', W / 2, 250, 60, '#5f8');
      text('Score: ' + score + ' / ' + WIN_SCORE, W / 2, 305, 28, '#fff');
      text(newBest ? 'NEW BEST!' : 'Best: ' + best, W / 2, 342, 20, newBest ? '#ffd84a' : '#889');
      text('Survived ' + Math.floor(time) + 's', W / 2, 370, 18, '#9af');
      text('Click or press SPACE to play again', W / 2, 430, 22, '#ffd84a');
    }
    ctx.restore();
  }

  function loop(t) {
    const dt = Math.min(0.05, (t - last) / 1000 || 0);
    last = t;
    update(dt);
    draw();
    sync();
    requestAnimationFrame(loop);
  }
  reset();
  sync();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
